with deduped as (select * from (select *, row_number() over (partition by order_id order by paid_at nulls last, id) as rn from payments) t where rn = 1), kept_keys as (select order_id, status from deduped except distinct select order_id, status from payments where status = 'REFUNDED'), kept_rows as (select s.* from deduped s inner join kept_keys k on s.order_id = k.order_id and s.status = k.status), valid as (select id, order_id, method, amount, status, rn, concat(status, ' - ', method) as status_method from kept_rows where status = 'SUCCESS'), base as (select id, order_id, method, rn, status_method, trim(method) as clean_method, coalesce(method, 'UNKNOWN') as method_filled from valid where rn >= 1), filtered as (select id, method, status_method, clean_method, method_filled, substring(method, 1, 4) as method_prefix, coalesce(method, 'N/A') as method_clean from base where order_id is not null and order_id in (25, 31)), filtered_payments as (select method, clean_method, method_prefix, method_clean, substring(method, 1, 4) as method_prefix_2 from filtered where method is not null), cleaned as (select clean_method, method_clean, method_prefix_2, length(method) as method_length from filtered_payments where method is not null) select clean_method, method_clean, method_length from cleaned order by method_length
